mapper.select:
SELECT , u.name AS farmer_name, c.name AS category_name FROM forum_topics t LEFT JOIN sys_user u ON t.farmer_id = u.id LEFT JOIN forum_categories c ON t.category_id = c.id
AND t.title LIKE '%' + #{title} + '%'
AND t.category_id = #{categoryId}
AND t.farmer_id = #{farmerId}
ORDER BY t.is_pinned DESC, t.created_at DESC

mapper.update:
UPDATE forum_topics
title = #{title}, content = #{content}, category_id = #{categoryId}, is_pinned = #{isPinned}, updated_at = GETDATE()
WHERE id = #{id}

UPDATE forum_topics
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE forum_topics
SET is_pinned = #{isPinned}, updated_at = GETDATE()
WHERE id = #{id}
